# Test what happens when @reraise is used as a decorator
from funcy import reraise

@reraise(ValueError, TypeError)
def f():
    raise ValueError("original error")

print(f"Type of f: {type(f)}")
print(f"f is callable: {callable(f)}")

try:
    result = f()
    print(f"f() returned: {result}")
except TypeError as e:
    print(f"Caught TypeError: {e}, __cause__: {e.__cause__}")
except ValueError as e:
    print(f"Caught ValueError: {e}")
